SCHEMA_SQL = "\nPRAGMA user_version=2;\nCREATE TABLE owner(singleton INTEGER PRIMARY KEY CHECK(singleton=1), binding_json TEXT NOT NULL, policy_sha256 TEXT NOT NULL);\nCREATE TABLE attempts(\n attempt_id TEXT PRIMARY KEY,\n operation TEXT NOT NULL CHECK(operation IN ('asr_wav','manual_response','public_speech_pair','text_http','tts_cosyvoice','tts_qwen_voice_clone')),\n quote_micro_cny INTEGER NOT NULL CHECK(typeof(quote_micro_cny)='integer' AND quote_micro_cny BETWEEN 1 AND 50000000),\n step_count INTEGER NOT NULL CHECK(typeof(step_count)='integer' AND step_count IN (1,2)),\n basis_json TEXT NOT NULL,\n created_ns INTEGER NOT NULL CHECK(typeof(created_ns)='integer')\n);\nCREATE TABLE steps(\n attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),\n ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal IN (0,1)),\n quote_micro_cny INTEGER NOT NULL CHECK(typeof(quote_micro_cny)='integer' AND quote_micro_cny BETWEEN 1 AND 50000000),\n state TEXT NOT NULL CHECK(state IN ('reserved','dispatching','unknown','closed','settled')),\n claim_nonce TEXT,\n PRIMARY KEY(attempt_id,ordinal),\n CHECK((state='reserved' AND claim_nonce IS NULL) OR (state!='reserved' AND claim_nonce IS NOT NULL\n  AND typeof(claim_nonce)='text' AND length(claim_nonce)=32 AND claim_nonce NOT GLOB '*[^0-9a-f]*'))\n);\nCREATE TABLE run_control(singleton INTEGER PRIMARY KEY CHECK(singleton=1), state TEXT NOT NULL CHECK(state IN ('ACTIVE','POISONED')));\nINSERT INTO run_control VALUES(1,'ACTIVE');\nCREATE TABLE text_dispatch(attempt_id TEXT PRIMARY KEY REFERENCES attempts(attempt_id), claim_nonce TEXT NOT NULL UNIQUE,\n owner_instance TEXT NOT NULL CHECK(length(owner_instance)=32));\nCREATE TABLE settlements(attempt_id TEXT PRIMARY KEY REFERENCES text_dispatch(attempt_id), claim_nonce TEXT NOT NULL UNIQUE,\n owner_instance TEXT NOT NULL, prompt_tokens INTEGER NOT NULL CHECK(typeof(prompt_tokens)='integer' AND prompt_tokens>=0),\n completion_tokens INTEGER NOT NULL CHECK(typeof(completion_tokens)='integer' AND completion_tokens>=0),\n total_tokens INTEGER NOT NULL CHECK(typeof(total_tokens)='integer' AND total_tokens=prompt_tokens+completion_tokens),\n reported_model TEXT NOT NULL, charged_micro_cny INTEGER NOT NULL CHECK(typeof(charged_micro_cny)='integer' AND charged_micro_cny>=0),\n evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64));\nCREATE TRIGGER control_monotonic BEFORE UPDATE ON run_control WHEN NEW.singleton IS NOT OLD.singleton OR NOT(OLD.state='ACTIVE' AND NEW.state='POISONED')\nBEGIN SELECT RAISE(ABORT,'poison monotonic'); END;\nCREATE TRIGGER control_no_delete BEFORE DELETE ON run_control BEGIN SELECT RAISE(ABORT,'poison permanent'); END;\nCREATE TRIGGER dispatch_no_update BEFORE UPDATE ON text_dispatch BEGIN SELECT RAISE(ABORT,'dispatch immutable'); END;\nCREATE TRIGGER dispatch_no_delete BEFORE DELETE ON text_dispatch BEGIN SELECT RAISE(ABORT,'dispatch immutable'); END;\nCREATE TRIGGER settlement_no_update BEFORE UPDATE ON settlements BEGIN SELECT RAISE(ABORT,'settlement immutable'); END;\nCREATE TRIGGER settlement_no_delete BEFORE DELETE ON settlements BEGIN SELECT RAISE(ABORT,'settlement immutable'); END;\nCREATE TRIGGER owner_no_update BEFORE UPDATE ON owner BEGIN SELECT RAISE(ABORT,'owner immutable'); END;\nCREATE TRIGGER owner_no_delete BEFORE DELETE ON owner BEGIN SELECT RAISE(ABORT,'owner immutable'); END;\nCREATE TRIGGER attempt_no_update BEFORE UPDATE ON attempts BEGIN SELECT RAISE(ABORT,'quote immutable'); END;\nCREATE TRIGGER attempt_no_delete BEFORE DELETE ON attempts BEGIN SELECT RAISE(ABORT,'quote immutable'); END;\nCREATE TRIGGER step_no_delete BEFORE DELETE ON steps BEGIN SELECT RAISE(ABORT,'quote immutable'); END;\nCREATE TRIGGER step_transition BEFORE UPDATE ON steps\nWHEN NEW.attempt_id IS NOT OLD.attempt_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.quote_micro_cny IS NOT OLD.quote_micro_cny\n OR NOT ((OLD.state='reserved' AND NEW.state='dispatching' AND OLD.claim_nonce IS NULL AND NEW.claim_nonce IS NOT NULL)\n OR (OLD.state='dispatching' AND NEW.state IN ('unknown','closed','settled') AND NEW.claim_nonce IS OLD.claim_nonce))\nBEGIN SELECT RAISE(ABORT,'invalid monotonic transition'); END;\n"
